func HeldLockSaveMessageBody(w *TableMessageWriter, value *HeldLock) bool {
	{
		if value.IdLength < 0 || value.IdLength > 256 {
			return false
		}
		if value.IdLength > 0 {
			w.Put(33, TableMessageRefBitsHere)
			if value.IdLength < 0 || value.IdLength > 256 {
				return false
			}
			w.Put(uint64(value.IdLength), 9)
			w.Raw(value.Id[:value.IdLength])
		}
	}
	{
		if value.VerbLength < 0 || value.VerbLength > 80 {
			return false
		}
		if value.VerbLength > 0 {
			w.Put(34, TableMessageRefBitsHere)
			if value.VerbLength < 0 || value.VerbLength > 80 {
				return false
			}
			w.Put(uint64(value.VerbLength), 7)
			w.Raw(value.Verb[:value.VerbLength])
		}
	}
	{
		if value.At != 0 {
			w.Put(35, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 5, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.At), uint64(0))
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func HeldLockMeasureMessages(values []*HeldLock, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !HeldLockSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func HeldLockSaveMessages(values []*HeldLock, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !HeldLockSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func HeldLockLoadMessageBody(r *TableMessageReader, value *HeldLock) bool {
	HeldLockReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x08b72e07b55c3ac0:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(256)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Id[:])
					copy(value.Id[:], text[:kept])
					value.IdLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x673ebb0102773a20:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(80)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Verb[:])
					copy(value.Verb[:], text[:kept])
					value.VerbLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x089c4e07b545a968:
			{
				widened := false
				if entry.Shape.Kind != 5 || entry.Element.Kind != 0 {
					if entry.Element.Kind == 0 && tableKindWidens(entry.Shape.Kind, 5) {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					var raw [16]byte
					if !tableMessageReadScalar(&r.Bits, entry.Shape, &raw) {
						r.Report.Malformed = true
						return false
					}
					payload1 := TableReader{Buffer: raw[:], Report: &r.Report}
					if !payload1.Has(tableKindBytes(entry.Shape.Kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := payload1.Signed(entry.Shape.Kind)
						value.At = int64(v)
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func HeldLockLoadMessages(values []HeldLock, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !HeldLockLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// TimerReset restores Timer's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TimerReset(value *Timer) {
	clear(value.Id[:])
	value.IdLength = 0
	clear(value.Wakes[:])
	value.WakesLength = 0
	value.Due = 0
	clear(value.Note[:])
	value.NoteLength = 0
	clear(value.By[:])
	value.ByLength = 0
	value.Set = 0
}

func TimerMeasureBody(value *Timer, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TimerSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TimerMeasure(value *Timer) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !TimerSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func TimerMeasureReason(value *Timer) (int64, error) {
	size := TimerMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
