func MemberListSaveMessageBody(w *TableMessageWriter, value *MemberList) bool {
	{
		if value.MembersCount < 0 || value.MembersCount > 128 {
			return false
		}
		if value.MembersCount > 0 {
			w.Put(53, TableMessageRefBitsHere)
			if value.MembersCount < 0 || value.MembersCount > 128 {
				return false
			}
			w.Put(uint64(value.MembersCount)-0, 8)
			for i := 0; i < int(value.MembersCount); i++ {
				if !MemberSaveMessageBody(w, &value.Members[i]) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func MemberListMeasureMessages(values []*MemberList, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !MemberListSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func MemberListSaveMessages(values []*MemberList, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !MemberListSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func MemberListLoadMessageBody(r *TableMessageReader, value *MemberList) bool {
	MemberListReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x79d594675e391090:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					base := &value.Members
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					keep := min(n, uint64(128))
					if keep < n {
						r.Report.Clamped++
					}
					walk := n
					if element.Shape.Bits >= 0 {
						walk = keep
					}
					for i := uint64(0); i < walk; i++ {
						var scratch Member
						p := &scratch
						if i < keep {
							p = &base[i]
						}
						if !MemberLoadMessageBody(r, &(*p)) {
							return false
						}
					}
					if walk < n && !r.Bits.Skip(int64(n-walk)*element.Shape.Bits) {
						r.Report.Malformed = true
						return false
					}
					value.MembersCount = int32(keep)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func MemberListLoadMessages(values []MemberList, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !MemberListLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ChangeEventReset restores ChangeEvent's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ChangeEventReset(value *ChangeEvent) {
	clear(value.Epoch[:])
	value.EpochLength = 0
	clear(value.Verb[:])
	value.VerbLength = 0
	value.RevBefore = 0
	value.RevAfter = 0
	for i := range value.Members {
		MemberReset(&value.Members[i])
	}
	value.MembersCount = 0
	for i := range value.BatchMembers {
		MemberReset(&value.BatchMembers[i])
	}
	value.BatchMembersCount = 0
}

func ChangeEventMeasureBody(value *ChangeEvent, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ChangeEventSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ChangeEventMeasure(value *ChangeEvent) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ChangeEventSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ChangeEventMeasureReason(value *ChangeEvent) (int64, error) {
	size := ChangeEventMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
