func CoordinatorDeliveryLoadMessages(values []CoordinatorDelivery, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !CoordinatorDeliveryLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// NoteReset restores Note's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func NoteReset(value *Note) {
	clear(value.Id[:])
	value.IdLength = 0
	clear(value.SafeDefault[:])
	value.SafeDefaultLength = 0
	value.DefaultCoordinatorTold = false
	value.DefaultOwnerTold = false
	clear(value.Alias[:])
	value.AliasLength = 0
	clear(value.Kind[:])
	value.KindLength = 0
	clear(value.NoteType[:])
	value.NoteTypeLength = 0
	clear(value.Stream[:])
	value.StreamLength = 0
	for i := range value.Primaries {
		Name256Reset(&value.Primaries[i])
	}
	value.PrimariesCount = 0
	value.Count = 0
	clear(value.What[:])
	value.WhatLength = 0
	clear(value.Who[:])
	value.WhoLength = 0
	value.Attempt = 0
	value.Before = 0
	value.At = 0
	for i := range value.Decisions {
		Name128Reset(&value.Decisions[i])
	}
	value.DecisionsCount = 0
	value.Marked = false
	clear(value.Answers[:])
	value.AnswersLength = 0
	for i := range value.Suspects {
		Name256Reset(&value.Suspects[i])
	}
	value.SuspectsCount = 0
	clear(value.Card[:])
	value.CardLength = 0
	clear(value.Other[:])
	value.OtherLength = 0
	clear(value.Tier[:])
	value.TierLength = 0
	clear(value.OtherStream[:])
	value.OtherStreamLength = 0
	value.StreamLevel = false
	value.SprintLevel = false
	for i := range value.Needs {
		Name256Reset(&value.Needs[i])
	}
	value.NeedsCount = 0
	value.Review = 0
	value.ReviewSet = 0
	clear(value.To[:])
	value.ToLength = 0
	clear(value.Hint[:])
	value.HintLength = 0
	StreamTransitionReset(&value.StreamTransition)
	value.StreamTransitionPresent = false
	DecisionDeliveryReset(&value.DecisionDelivery)
	value.DecisionDeliveryPresent = false
	CoordinatorDeliveryReset(&value.CoordinatorDelivery)
	value.CoordinatorDeliveryPresent = false
}

func NoteMeasureBody(value *Note, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !NoteSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func NoteMeasure(value *Note) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !NoteSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func NoteMeasureReason(value *Note) (int64, error) {
	size := NoteMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
