const PairSaveRetainMessages = "Pair: retention requires a region round trip through the VARIABLE form"
const PairLoadRetainMessages = "Pair: retention requires a region round trip through the VARIABLE form"
const PairLoadRetain = "Pair: retention requires a variable root and its region directory"
