const PairSaveRetain = "Pair: retention requires a variable root and its region directory"

func PairCookMeasure(value *Pair) int64                { return 384 }
func PairCookMeasureReason(value *Pair) (int64, error) { return PairCookMeasure(value), nil }
func PairCookFrom(value *Pair, buffer []byte, order TableByteOrder) bool {
	return tableCookFixed(unsafe.Pointer(value), PairTableType(), buffer, order)
}
func PairSaveMessageBody(w *TableMessageWriter, value *Pair) bool {
	{
		if value.NameLength < 0 || value.NameLength > 32 {
			return false
		}
		if value.NameLength > 0 {
			w.Put(104, TableMessageRefBitsHere)
			if value.NameLength < 0 || value.NameLength > 32 {
				return false
			}
			w.Put(uint64(value.NameLength), 6)
			w.Raw(value.Name[:value.NameLength])
		}
	}
	{
		if value.ValueLength < 0 || value.ValueLength > 256 {
			return false
		}
		if value.ValueLength > 0 {
			w.Put(55, TableMessageRefBitsHere)
			if value.ValueLength < 0 || value.ValueLength > 256 {
				return false
			}
			w.Put(uint64(value.ValueLength), 9)
			w.Raw(value.Value[:value.ValueLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func PairMeasureMessages(values []*Pair, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !PairSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func PairSaveMessages(values []*Pair, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !PairSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func PairLoadMessageBody(r *TableMessageReader, value *Pair) bool {
	PairReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0xc4bcadba8e631b86:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(32)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Name[:])
					copy(value.Name[:], text[:kept])
					value.NameLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x7ce4fd9430e80cea:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(256)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Value[:])
					copy(value.Value[:], text[:kept])
					value.ValueLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func PairLoadMessages(values []Pair, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !PairLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// LogLineReset restores LogLine's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LogLineReset(value *LogLine) {
	clear(value.Kind[:])
	value.KindLength = 0
	value.At = 0
	value.Epoch = 0
	clear(value.Op[:])
	value.OpLength = 0
	clear(value.Card[:])
	value.CardLength = 0
	for i := range value.Cards {
		Name256Reset(&value.Cards[i])
	}
	value.CardsCount = 0
	clear(value.Primary[:])
	value.PrimaryLength = 0
	clear(value.Stream[:])
	value.StreamLength = 0
	clear(value.TableName[:])
	value.TableNameLength = 0
	clear(value.From[:])
	value.FromLength = 0
	clear(value.To[:])
	value.ToLength = 0
	value.Removed = false
	value.Gen = 0
	clear(value.Actor[:])
	value.ActorLength = 0
	clear(value.Verb[:])
	value.VerbLength = 0
	clear(value.Cause[:])
	value.CauseLength = 0
	for i := range value.Answers {
		Name128Reset(&value.Answers[i])
	}
	value.AnswersCount = 0
	for i := range value.Text {
		TextRefReset(&value.Text[i])
	}
	value.TextCount = 0
	for i := range value.Set {
		PairReset(&value.Set[i])
	}
	value.SetCount = 0
	NoteReset(&value.Note)
	value.NotePresent = false
}

func LogLineMeasureBody(value *LogLine, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !LogLineSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func LogLineMeasure(value *LogLine) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !LogLineSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func LogLineMeasureReason(value *LogLine) (int64, error) {
	size := LogLineMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
