func SeatChangeLoadMessages(values []SeatChange, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !SeatChangeLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// PropWriteReset restores PropWrite's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func PropWriteReset(value *PropWrite) {
	clear(value.TableName[:])
	value.TableNameLength = 0
	clear(value.Name[:])
	value.NameLength = 0
	clear(value.Value[:])
	value.ValueLength = 0
	clear(value.Was[:])
	value.WasLength = 0
	value.WasAbsent = false
}

func PropWriteMeasureBody(value *PropWrite, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !PropWriteSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func PropWriteMeasure(value *PropWrite) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !PropWriteSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func PropWriteMeasureReason(value *PropWrite) (int64, error) {
	size := PropWriteMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
