func PropWriteSaveMessageBody(w *TableMessageWriter, value *PropWrite) bool {
	{
		if value.TableNameLength < 0 || value.TableNameLength > 128 {
			return false
		}
		if value.TableNameLength > 0 {
			w.Put(42, TableMessageRefBitsHere)
			if value.TableNameLength < 0 || value.TableNameLength > 128 {
				return false
			}
			w.Put(uint64(value.TableNameLength), 8)
			w.Raw(value.TableName[:value.TableNameLength])
		}
	}
	{
		if value.NameLength < 0 || value.NameLength > 128 {
			return false
		}
		if value.NameLength > 0 {
			w.Put(105, TableMessageRefBitsHere)
			if value.NameLength < 0 || value.NameLength > 128 {
				return false
			}
			w.Put(uint64(value.NameLength), 8)
			w.Raw(value.Name[:value.NameLength])
		}
	}
	{
		if value.ValueLength < 0 || value.ValueLength > 1024 {
			return false
		}
		if value.ValueLength > 0 {
			w.Put(106, TableMessageRefBitsHere)
			if value.ValueLength < 0 || value.ValueLength > 1024 {
				return false
			}
			w.Put(uint64(value.ValueLength), 11)
			w.Raw(value.Value[:value.ValueLength])
		}
	}
	{
		if value.WasLength < 0 || value.WasLength > 1024 {
			return false
		}
		if value.WasLength > 0 {
			w.Put(107, TableMessageRefBitsHere)
			if value.WasLength < 0 || value.WasLength > 1024 {
				return false
			}
			w.Put(uint64(value.WasLength), 11)
			w.Raw(value.Was[:value.WasLength])
		}
	}
	{
		if value.WasAbsent != false {
			w.Put(108, TableMessageRefBitsHere)
			if value.WasAbsent {
				w.Put(1, 1)
			} else {
				w.Put(0, 1)
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func PropWriteMeasureMessages(values []*PropWrite, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !PropWriteSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func PropWriteSaveMessages(values []*PropWrite, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !PropWriteSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
