func OpQueuedLoadMessages(values []OpQueued, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !OpQueuedLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ChunkReset restores Chunk's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ChunkReset(value *Chunk) {
	clear(value.OpId[:])
	value.OpIdLength = 0
	clear(value.Kind[:])
	value.KindLength = 0
	clear(value.Key[:])
	value.KeyLength = 0
	value.Index = 0
	value.Count = 0
	clear(value.Data[:])
	value.DataLength = 0
}

func ChunkMeasureBody(value *Chunk, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ChunkSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ChunkMeasure(value *Chunk) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ChunkSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ChunkMeasureReason(value *Chunk) (int64, error) {
	size := ChunkMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
