func ChunkLoadMessages(values []Chunk, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !ChunkLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// RefusalReset restores Refusal's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RefusalReset(value *Refusal) {
	clear(value.Id[:])
	value.IdLength = 0
	clear(value.Why[:])
	value.WhyLength = 0
}

func RefusalMeasureBody(value *Refusal, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !RefusalSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func RefusalMeasure(value *Refusal) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !RefusalSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RefusalMeasureReason(value *Refusal) (int64, error) {
	size := RefusalMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func RefusalSaveBody(w *TableWriter, value *Refusal) bool {
	{
		if value.IdLength < 0 || value.IdLength > 256 {
			return false
		}
		if value.IdLength > 0 {
			if ref := w.Ids.refAtHit(7, 0x08b72e07b55c3ac0); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.IdLength < 0 || value.IdLength > 256 {
				return false
			}
			if !w.putLebPair(uint64(value.IdLength)) {
				w.putLebWide(uint64(value.IdLength))
			}
			w.Raw(value.Id[:value.IdLength])
		}
	}
	{
		if value.WhyLength < 0 || value.WhyLength > 512 {
			return false
		}
		if value.WhyLength > 0 {
			if ref := w.Ids.refAtHit(60, 0x5ec5ea1948914a79); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.WhyLength < 0 || value.WhyLength > 512 {
				return false
			}
			if !w.putLebPair(uint64(value.WhyLength)) {
				w.putLebWide(uint64(value.WhyLength))
			}
			w.Raw(value.Why[:value.WhyLength])
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func RefusalSave(value *Refusal, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !RefusalSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RefusalLoadBody(r *TableReader, value *Refusal) bool {
	RefusalReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x08b72e07b55c3ac0: // id
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Id[:])
				value.IdLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 256 {
				keep = tableUtf8Clamp(sub.Buffer, 256)
				r.Report.Clamped++
			}
			clear(value.Id[:])
			copy(value.Id[:keep], sub.Buffer)
			value.IdLength = int32(keep)
		case 0x5ec5ea1948914a79: // why
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Why[:])
				value.WhyLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 512 {
				keep = tableUtf8Clamp(sub.Buffer, 512)
				r.Report.Clamped++
			}
			clear(value.Why[:])
			copy(value.Why[:keep], sub.Buffer)
			value.WhyLength = int32(keep)
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// Refusal also carries the FIXED form (form 3): RefusalFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func RefusalLoad(value *Refusal, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		RefusalReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !RefusalLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			RefusalReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		RefusalReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

