func StepResultLoadMessages(values []StepResult, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !StepResultLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ---- THE FIXED FORM, form byte 3 (docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's layout and then the values
// in declared order, every field at its declared storage width. The writer is
// constant-offset stores; the reader is ONE loop over ONE plan.

func Name128FixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	out[n] = TableFixedEntry{Src: src + 0, Dst: dst + uint32(unsafe.Offsetof(Name128{}.ValueLength)), Size: 128, Aux: dst + uint32(unsafe.Offsetof(Name128{}.Value)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // value
	n++
	return n
}

func Name128FixedWriteBody(b []byte, value *Name128) {
	tableFixedPut32(b[0:], uint32(value.ValueLength))
	copy(b[0:][4:], value.Value[:])
}

