// THE READ-SIDE BOUNDS (docs/SPEC-TABLES.md §3.4): a ranged scalar's
// declared min and max, and an ORDINAL's set — a union tag past the arm
// count, an enum ordinal past the enum's top value. Straight-line, after
// the copy, over STORAGE, so the identity plan and a plan compiled from a
// stranger's layout are held to the same numbers by the same pass. Every
// clamp COUNTS. The pass walks LIVE elements only: a counted array's live
// count, not its slack; an optional's payload only when present; a union's
// set arm, not the others.
func Name128FixedClamp(value *Name128, report *TableReport) {
	clamped := int32(0)
	Name128FixedClampBody(value, &clamped)
	report.Clamped += clamped
}

// ---- Name128, the fixed form ----

const Name128FixedBodyBytes = 132
const Name128FixedRecordBytes = 8 + Name128FixedBodyBytes
const Name128FixedHash = 0xaf800f7b8e5760d0

var Name128FixedLayout = []byte{
	0x02, 0x00, 0x00, 0x00, 0x27, 0xd8, 0x81, 0x78, 0x23, 0x00, 0x96, 0xc3, 0x0d, 0x84, 0x00, 0x00,
	0x00, 0x01, 0x00, 0x00, 0x00, 0xea, 0x0c, 0xe8, 0x30, 0x94, 0xfd, 0xe4, 0x7c, 0x0c, 0x84, 0x00,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
}

var Name128FixedDst = []TableFixedDst{
	{0, 0, 0, 0, 0, 0}, // Name128
	{uint32(unsafe.Offsetof(Name128{}.ValueLength)), 0, uint32(unsafe.Offsetof(Name128{}.Value)), 0, 1, 1}, // value
}

var Name128FixedPlan = tableFixedBuildPlan(Name128FixedLeaves, 1)

var Name128FixedKnown = []TableFixedKnownLayout{
	{
		Hash:        0xaf800f7b8e5760d0,
		LayoutBytes: 38,
		Record:      140,
		Layout: []byte{
			0x02, 0x00, 0x00, 0x00, 0x27, 0xd8, 0x81, 0x78, 0x23, 0x00, 0x96, 0xc3, 0x0d, 0x84, 0x00, 0x00,
			0x00, 0x01, 0x00, 0x00, 0x00, 0xea, 0x0c, 0xe8, 0x30, 0x94, 0xfd, 0xe4, 0x7c, 0x0c, 0x84, 0x00,
			0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
		},
	},
}

// The floor: below it a layout this build once served is retired, and
// the answer is layout_unsupported rather than layout_newer (§5.2).
const Name128FixedFloor = 0

// One plan per lineage entry, laid down from THE LOCK's bytes: nothing
// compiles on the load path (§5.8 row 3).
var Name128FixedLineagePlans = tableFixedLineagePlans(Name128FixedKnown, Name128FixedLayout, Name128FixedDst, Name128FixedHash)

// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func Name128FixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(Name128FixedLayout)) + count*Name128FixedRecordBytes
}

func Name128FixedSave(values []Name128, buffer []byte) int64 {
	need := Name128FixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], Name128FixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(Name128FixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], Name128FixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(Name128FixedLayout):]
	for k := range values {
		tableFixedPut64(at, Name128FixedHash)
		clear(at[8 : 8+Name128FixedBodyBytes])
		Name128FixedWriteBody(at[8:], &values[k])
		at = at[Name128FixedRecordBytes:]
	}
	return need
}

func Name128FixedLoad(values []Name128, data []byte, plan []TableFixedEntry, report *TableReport) int64 {
	if report == nil {
		var local TableReport
		report = &local
	}
	*report = TableReport{}
	if len(data) < 1 {
		report.Malformed = true
		return -1
	}
	if data[0] != TableFixedForm {
		switch data[0] {
		case 1: // the VARIABLE form, and the only form this one is newer than
			return tableFixedRefuse(report, "previous_form")
		case 2: // the MESSAGE form: a form this build carries, through another surface
			return tableFixedRefuse(report, "message_form_as_file")
		}
		return tableFixedRefuse(report, "newer_form")
	}
	if len(data) < TableFixedHeaderBytes+4 {
		report.Malformed = true
		return -1
	}
	for _, reserved := range data[1:TableFixedHashAt] {
		if reserved != 0 {
			report.Malformed = true
			return -1
		}
	}
	layoutBytes := tableFixedGet32(data[TableFixedHeaderBytes:])
	if int64(layoutBytes)+TableFixedHeaderBytes+4 > int64(len(data)) {
		return tableFixedRefuse(report, "layout_malformed")
	}
	layout := data[TableFixedHeaderBytes+4 : TableFixedHeaderBytes+4+layoutBytes]
	hash := tableFixedGet64(data[TableFixedHashAt:])
	pick := tableFixedSelect(Name128FixedKnown, hash)
	if pick < 0 {
		return tableFixedRefuseHash(report, "layout_newer", hash)
	}
	if pick < Name128FixedFloor {
		return tableFixedRefuseHash(report, "layout_unsupported", hash)
	}
	known := &Name128FixedKnown[pick]
	if int(layoutBytes) != len(known.Layout) {
		return tableFixedRefuse(report, "layout_malformed")
	}
	for i := range layout {
		if layout[i] != known.Layout[i] {
			return tableFixedRefuse(report, "layout_malformed")
		}
	}
	entries := Name128FixedPlan.Entries
	entryCount := Name128FixedPlan.Count
	recordBytes := known.Record
	censusUnknown, censusKind := int32(0), int32(0)
	if hash != Name128FixedHash {
		lane := &Name128FixedLineagePlans[pick]
		if lane.Why != "" {
			return tableFixedRefuse(report, lane.Why)
		}
		entries, entryCount = lane.Entries, lane.Count
		// THE CENSUS IS ONCE PER PEER and never per record (§5.4), and it
		// lands only on a read that returns: REFUSE moves no counter.
		censusUnknown, censusKind = lane.Unknown, lane.KindMismatch
	}
	if int64(entryCount) > int64(len(plan)) {
		return tableFixedRefuse(report, "plan_too_large")
	}
	at := data[TableFixedHeaderBytes+4+layoutBytes:]
	rest := int64(len(data)) - TableFixedHeaderBytes - 4 - int64(layoutBytes)
	if recordBytes <= 8 || rest%recordBytes != 0 {
		report.Malformed = true
		return -1
	}
	n := rest / recordBytes
	if n > int64(len(values)) {
		return tableFixedRefuse(report, "batch_too_large")
	}
	var def Name128
	var defBytes []byte
	var holes []tableFixedHole
	if n > 0 {
		Name128Reset(&def)
		defBytes = tableFixedOverlay(unsafe.Pointer(&def), unsafe.Sizeof(def))
		holes = tableFixedHoles(entries, entryCount, uint32(len(defBytes)))
	}
	for k := int64(0); k < n; k++ {
		if tableFixedGet64(at) != hash {
			return tableFixedRefuse(report, "no_layout")
		}
		if why := tableFixedTextRefusal(entries, entryCount, at[8:recordBytes]); why != "" {
			return tableFixedRefuse(report, why)
		}
		dst := tableFixedOverlay(unsafe.Pointer(&values[k]), unsafe.Sizeof(values[k]))
		for i := range holes {
			h := holes[i]
			copy(dst[h.Off:h.Off+h.Size], defBytes[h.Off:h.Off+h.Size])
		}
		if why := tableFixedRun(entries, entryCount, at[8:recordBytes], dst, report); why != "" {
			return tableFixedRefuse(report, why)
		}
		tableFixedForgedBounds(entries, entryCount, at[8:recordBytes], report)
		// AND THE BOUNDS THE LOOP DOES NOT HOLD, straight-line over the
		// storage it just wrote: the same pass for either plan (§3.4).
		Name128FixedClamp(&values[k], report)
		at = at[recordBytes:]
	}
	report.Unknown += censusUnknown
	report.KindMismatch += censusKind
	return n
}

// THE READ-SIDE BOUNDS (docs/SPEC-TABLES.md §3.4): a ranged scalar's
// declared min and max, and an ORDINAL's set — a union tag past the arm
// count, an enum ordinal past the enum's top value. Straight-line, after
// the copy, over STORAGE, so the identity plan and a plan compiled from a
// stranger's layout are held to the same numbers by the same pass. Every
// clamp COUNTS. The pass walks LIVE elements only: a counted array's live
// count, not its slack; an optional's payload only when present; a union's
// set arm, not the others.
func Name256FixedClamp(value *Name256, report *TableReport) {
	clamped := int32(0)
	Name256FixedClampBody(value, &clamped)
	report.Clamped += clamped
}

