// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func TimersFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(TimersFixedLayout)) + count*TimersFixedRecordBytes
}

func TimersFixedSave(values []Timers, buffer []byte) int64 {
	need := TimersFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], TimersFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(TimersFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], TimersFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(TimersFixedLayout):]
	for k := range values {
		tableFixedPut64(at, TimersFixedHash)
		clear(at[8 : 8+TimersFixedBodyBytes])
		TimersFixedWriteBody(at[8:], &values[k])
		at = at[TimersFixedRecordBytes:]
	}
	return need
}

